-- Standard audit/system columns every iDempiere table needs (AD_Client_ID, AD_Org_ID, IsActive,
-- Created, CreatedBy, Updated, UpdatedBy) are omitted here for brevity — copy them verbatim from
-- any other DD_ table's AD_Column rows in this instance (e.g. DD_CompatibilityGroup) rather than
-- retyping them; they are identical on every custom table.


-- =====================================================================
-- PART 2 — Physical table (self-contained, no dictionary IDs needed)
-- =====================================================================
CREATE TABLE adempiere.dd_productnesting (
    dd_productnesting_id    NUMERIC(10)     NOT NULL,
    ad_client_id            NUMERIC(10)     NOT NULL,
    ad_org_id               NUMERIC(10)     NOT NULL,
    isactive                CHAR(1)         NOT NULL DEFAULT 'Y',
    created                 TIMESTAMP       NOT NULL DEFAULT now(),
    createdby               NUMERIC(10)     NOT NULL,
    updated                 TIMESTAMP       NOT NULL DEFAULT now(),
    updatedby               NUMERIC(10)     NOT NULL,
    classification          VARCHAR(40)     NOT NULL,
    nestingfamily           VARCHAR(40)     NOT NULL,
    seqno                   NUMERIC(10)     NOT NULL,
    nestedvolume            NUMERIC,        -- NULL = not measured yet, see PART 1 comment
    description             VARCHAR(255),
    uuid                    VARCHAR(36)     DEFAULT NULL,
    CONSTRAINT dd_productnesting_key PRIMARY KEY (dd_productnesting_id),
    -- one nesting definition per model — a Classification cannot belong to two families at once
    CONSTRAINT dd_productnesting_classification_uq UNIQUE (classification)
);

COMMENT ON TABLE adempiere.dd_productnesting IS
    'Which product models nest inside which other models of the same NestingFamily. One row per model (Classification), not per color variant. See ANIDADO_TANQUES_SAP.md in the plugin repo for the design.';
COMMENT ON COLUMN adempiere.dd_productnesting.nestedvolume IS
    'Marginal volume when nested inside a larger sibling. PENDING MEASUREMENT — NULL until real values exist.';
